package com.bank.fd.repository;

import com.bank.fd.dto.FdDto;
import com.bank.fd.model.FixedDeposit;
import com.bank.fd.projection.FdSummary;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Query;
import org.springframework.data.repository.query.Param;
import java.util.List;

public interface FixedDepositRepository extends JpaRepository<FixedDeposit, String> {

    // ═══ FORM 1: INTERFACE PROJECTION ═══
    // Spring Data narrows SQL to: SELECT f.fd_id, f.maturity_amount FROM fixed_deposits f WHERE f.account_id = ?
    List<FdSummary> findByAccountId(String accountId);

    // ═══ FORM 2: CLASS/DTO CONSTRUCTOR PROJECTION ═══
    // JPQL constructor expression — fully qualified class name, param order matches SELECT
    @Query("SELECT new com.bank.fd.dto.FdDto(f.fdId, f.principal, f.maturityAmount) " +
           "FROM FixedDeposit f WHERE f.status = :status")
    List<FdDto> findDtoByStatus(@Param("status") String status);

    // ═══ FORM 3: DYNAMIC PROJECTION ═══
    // One method, caller passes the projection Class at runtime.
    <T> List<T> findByAccountId(String accountId, Class<T> type);
}
