package com.bank.fd.service;

import com.bank.fd.dto.FdDto;
import com.bank.fd.model.FixedDeposit;
import com.bank.fd.projection.FdSummary;
import com.bank.fd.repository.FixedDepositRepository;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.util.List;

@Service
@RequiredArgsConstructor
@Slf4j
public class FdProjectionService {

    private final FixedDepositRepository fdRepo;

    // FORM 1: interface projection — 2 columns, proxy objects
    @Transactional(readOnly = true)
    public List<FdSummary> summaryByAccount(String accountId) {
        List<FdSummary> result = fdRepo.findByAccountId(accountId);
        log.info("[INTERFACE] {} rows, 2 columns (fd_id, maturity_amount)", result.size());
        return result;
    }

    // FORM 2: DTO constructor projection — 3 columns, plain records (fastest)
    @Transactional(readOnly = true)
    public List<FdDto> dtoByStatus(String status) {
        List<FdDto> result = fdRepo.findDtoByStatus(status);
        log.info("[DTO] {} rows, 3 columns (fd_id, principal, maturity_amount) — plain records", result.size());
        return result;
    }

    // FORM 3: dynamic projection — caller chooses the shape
    @Transactional(readOnly = true)
    public List<FdDto> dynamicByAccount(String accountId) {
        List<FdDto> result = fdRepo.findByAccountId(accountId, FdDto.class);
        log.info("[DYNAMIC] {} rows returned as FdDto (could also be FdSummary or FixedDeposit)", result.size());
        return result;
    }
}
