package com.bank.fd.controller;

import com.bank.fd.dto.FdDto;
import com.bank.fd.projection.FdSummary;
import com.bank.fd.service.FdProjectionService;
import lombok.RequiredArgsConstructor;
import org.springframework.web.bind.annotation.*;
import java.util.List;

@RestController
@RequestMapping("/api/v1/fd-projections")
@RequiredArgsConstructor
public class FdProjectionController {

    private final FdProjectionService service;

    @GetMapping("/summary/{accountId}")
    public List<FdSummary> summary(@PathVariable String accountId) {
        return service.summaryByAccount(accountId);
    }

    @GetMapping("/dto")
    public List<FdDto> dto(@RequestParam(defaultValue = "ACTIVE") String status) {
        return service.dtoByStatus(status);
    }

    @GetMapping("/dynamic/{accountId}")
    public List<FdDto> dynamic(@PathVariable String accountId) {
        return service.dynamicByAccount(accountId);
    }
}
