package com.bank.fd.service;

import com.bank.fd.dto.FdDto;
import org.junit.jupiter.api.Test;
import java.math.BigDecimal;
import static org.assertj.core.api.Assertions.*;

class FdProjectionTest {

    @Test
    void dtoRecordCarriesOnlyChosenFields() {
        FdDto dto = new FdDto("FD-001", new BigDecimal("500000"), new BigDecimal("536250"));
        assertThat(dto.fdId()).isEqualTo("FD-001");
        assertThat(dto.principal()).isEqualByComparingTo("500000");
        assertThat(dto.maturityAmount()).isEqualByComparingTo("536250");
        // No holderName, no notes, no branchCode — not fetched, not stored.
    }

    @Test
    void dtoRecordEqualityByValue() {
        FdDto a = new FdDto("FD-001", new BigDecimal("500000"), new BigDecimal("536250"));
        FdDto b = new FdDto("FD-001", new BigDecimal("500000"), new BigDecimal("536250"));
        assertThat(a).isEqualTo(b);
    }

    @Test
    void projectionColumnSavings() {
        // Full entity: 12 columns. DTO projection: 3 columns.
        int full = 12, dto = 3;
        double savings = 1.0 - ((double) dto / full);
        assertThat(savings).isGreaterThan(0.7); // >70% fewer columns
    }
}
